            uint256 defi5Balance = IERC20(DEFI5).balanceOf(address(this));
            console.log("Burning %s DEFI5 tokens", defi5Balance / 1e18);
            indexPool.exitPool(defi5Balance, minAmountOut);
            printBalances();
        }
