/* -------------------- Interface -------------------- */
interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(
        address account
    ) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IIndexPool {
    function joinswapExternAmountIn(
        address tokenIn,
        uint256 tokenAmountIn,
        uint256 minPoolAmountOut
    ) external returns (uint256); /* poolAmountOut */

    function exitPool(uint256 poolAmountIn, uint256[] calldata minAmountsOut) external;

    function gulp(
        address token
    ) external;

    function swapExactAmountIn(
        address tokenIn,
        uint256 tokenAmountIn,
        address tokenOut,
        uint256 minAmountOut,
        uint256 maxPrice
    ) external returns (uint256, /* tokenAmountOut */ uint256); /* spotPriceAfter */

    function extrapolatePoolValueFromToken() external view returns (address, /* token */ uint256); /* extrapolatedValue */

    function getTotalDenormalizedWeight() external view returns (uint256);

    function getBalance(
        address token
    ) external view returns (uint256);
}

interface IMarketCapSqrtController {
    function updateMinimumBalance(IIndexPool pool, address tokenAddress) external;
    function reindexPool(
        address poolAddress
    ) external;
}

interface IUniswapV2Pair {
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes memory data) external;
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface IUniswapV2Router01 {
    function swapTokensForExactTokens(
        uint256 amountOut,
        uint256 amountInMax,
        address[] memory path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);
}

